// Sound System (Web Audio API)
class SoundFx {
  constructor() {
    this.ctx = null;
    this.sipNode = null;
    this.sipGain = null;
    this.isSipping = false;
  }
  init() {
    if (!this.ctx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (AudioContext) this.ctx = new AudioContext();
    }
    if (this.ctx && this.ctx.state === "suspended") {
      this.ctx.resume().catch(() => {});
    }
  }
  startSip() {
    this.init();
    if (!this.ctx || this.isSipping) return;
    this.isSipping = true;
    try {
      // Gentle filtered bubbly noise for straw suction
      const bufferSize = this.ctx.sampleRate * 1.5;
      const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const output = noiseBuffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        output[i] = Math.random() * 2 - 1;
      }
      const whiteNoise = this.ctx.createBufferSource();
      whiteNoise.buffer = noiseBuffer;
      whiteNoise.loop = true;

      const filter = this.ctx.createBiquadFilter();
      filter.type = "bandpass";
      filter.frequency.setValueAtTime(650, this.ctx.currentTime);
      filter.Q.setValueAtTime(4.0, this.ctx.currentTime);

      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(0.01, this.ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.08, this.ctx.currentTime + 0.15);

      whiteNoise.connect(filter);
      filter.connect(gain);
      gain.connect(this.ctx.destination);
      whiteNoise.start();

      this.sipNode = whiteNoise;
      this.sipGain = gain;
    } catch (e) {}
  }
  stopSip() {
    if (!this.isSipping) return;
    this.isSipping = false;
    if (this.sipGain && this.ctx) {
      try {
        this.sipGain.gain.linearRampToValueAtTime(0.001, this.ctx.currentTime + 0.08);
        setTimeout(() => {
          if (this.sipNode) {
            try { this.sipNode.stop(); this.sipNode.disconnect(); } catch (e) {}
            this.sipNode = null;
          }
        }, 100);
      } catch (e) {}
    }
  }
  playClink() {
    this.init();
    if (!this.ctx) return;
    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(2400 + Math.random() * 400, this.ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(1200, this.ctx.currentTime + 0.15);
      gain.gain.setValueAtTime(0.06, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.18);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start();
      osc.stop(this.ctx.currentTime + 0.2);
    } catch (e) {}
  }
  playSplash() {
    this.init();
    if (!this.ctx) return;
    try {
      [523.25, 659.25, 783.99, 1046.5].forEach((freq, i) => {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = "triangle";
        osc.frequency.setValueAtTime(freq, this.ctx.currentTime + i * 0.03);
        gain.gain.setValueAtTime(0.04, this.ctx.currentTime + i * 0.03);
        gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.45 + i * 0.03);
        osc.connect(gain);
        gain.connect(this.ctx.destination);
        osc.start(this.ctx.currentTime + i * 0.03);
        osc.stop(this.ctx.currentTime + 0.5 + i * 0.03);
      });
    } catch (e) {}
  }
}
const sfx = new SoundFx();

// Math & Vector Utilities
const V = {
  add: (a, b) => [a[0] + b[0], a[1] + b[1]],
  sub: (a, b) => [a[0] - b[0], a[1] - b[1]],
  mul: (a, s) => [a[0] * s, a[1] * s],
  dist: (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]),
  len: (a) => Math.hypot(a[0], a[1]) || 1e-6,
  norm: (a) => {
    const l = Math.hypot(a[0], a[1]) || 1e-6;
    return [a[0] / l, a[1] / l];
  },
  lerp: (a, b, t) => a + (b - a) * t,
  lerpV: (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t],
  clamp: (v, min, max) => Math.min(max, Math.max(min, v))
};

// Citrus Splashes & Sparkles Particle System
class ParticleSystem {
  constructor() {
    this.particles = [];
  }
  reset() {
    this.particles = [];
  }
  emitSplash(pos, count = 35) {
    for (let i = 0; i < count; i++) {
      const angle = (Math.random() * Math.PI * 2);
      const speed = 120 + Math.random() * 320;
      const size = 3 + Math.random() * 8;
      const life = 0.8 + Math.random() * 0.9;
      const isSparkle = Math.random() < 0.35;
      this.particles.push({
        x: pos[0] + (Math.random() - 0.5) * 20,
        y: pos[1] + (Math.random() - 0.5) * 20,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 100,
        r: size,
        life,
        maxLife: life,
        isSparkle,
        color: isSparkle ? "#FFF9C4" : (Math.random() < 0.6 ? "#FF8F00" : "#FFA726")
      });
    }
  }
  emitSipDroplets(pos, rate = 1) {
    if (Math.random() > 0.45 * rate) return;
    this.particles.push({
      x: pos[0] + (Math.random() - 0.5) * 12,
      y: pos[1] + (Math.random() - 0.5) * 12,
      vx: (Math.random() - 0.5) * 40,
      vy: -20 - Math.random() * 30,
      r: 2 + Math.random() * 3.5,
      life: 0.4 + Math.random() * 0.3,
      maxLife: 0.7,
      isSparkle: Math.random() < 0.4,
      color: "#FFD54F"
    });
  }
  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 320 * dt;
      p.vx *= 0.96;
    }
  }
  draw(ctx) {
    ctx.save();
    for (const p of this.particles) {
      const alpha = Math.max(0, p.life / p.maxLife);
      ctx.globalAlpha = alpha;
      ctx.fillStyle = p.color;
      if (p.isSparkle) {
        const r = p.r * 1.3;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y - r);
        ctx.quadraticCurveTo(p.x, p.y, p.x + r, p.y);
        ctx.quadraticCurveTo(p.x, p.y, p.x, p.y + r);
        ctx.quadraticCurveTo(p.x, p.y, p.x - r, p.y);
        ctx.quadraticCurveTo(p.x, p.y, p.x, p.y - r);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "rgba(255, 255, 255, 0.7)";
        ctx.beginPath();
        ctx.arc(p.x - p.r * 0.3, p.y - p.r * 0.3, p.r * 0.35, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
  }
}

// Transparent Glass & Orange Juice Renderer
class GlassDrinkRenderer {
  constructor(w, h) {
    this.w = w;
    this.h = h;
    this.liquidLevel = 0.82;
    this.targetLevel = 0.82;
    this.sipProgress = 0;
    this.fizz = [];
    this.pulp = [];
    this.condensation = [];
    this.ice = [
      { x: -28, y: -45, rot: 0.25, size: 46, bob: 0 },
      { x: 26, y: -55, rot: -0.32, size: 52, bob: 1.4 },
      { x: -4, y: -25, rot: 0.12, size: 42, bob: 2.7 }
    ];
    this.initDecorations();
  }

  resize(w, h) {
    this.w = w;
    this.h = h;
  }

  initDecorations() {
    this.fizz = [];
    for (let i = 0; i < 28; i++) {
      this.fizz.push({
        x: (Math.random() - 0.5) * 100,
        y: Math.random() * 200,
        r: 1 + Math.random() * 2.8,
        speed: 18 + Math.random() * 32,
        seed: Math.random() * 10
      });
    }

    this.pulp = [];
    for (let i = 0; i < 35; i++) {
      this.pulp.push({
        x: (Math.random() - 0.5) * 110,
        y: Math.random() * 210,
        rx: 1.5 + Math.random() * 2,
        ry: 2.5 + Math.random() * 3.5,
        rot: Math.random() * Math.PI,
        color: Math.random() < 0.6 ? "#FF8F00" : "#FFE082"
      });
    }

    this.condensation = [];
    for (let i = 0; i < 32; i++) {
      this.condensation.push({
        u: (Math.random() - 0.5) * 0.86,
        v: 0.15 + Math.random() * 0.72,
        r: 1.5 + Math.random() * 3.2,
        drip: Math.random() < 0.2 ? Math.random() * 15 : 0
      });
    }
  }

  refill() {
    this.targetLevel = 0.85;
    this.liquidLevel = 0.85;
  }

  drainSip(amount) {
    this.targetLevel = Math.max(0.0, this.targetLevel - amount);
  }

  getGlassBounds() {
    const cx = Math.max(this.w * 0.5, Math.min(this.w * 0.5, 340));
    const glassW = Math.min(this.w * 0.3, 175);
    const glassH = Math.min(this.h * 0.44, 300);
    const cy = this.h * 0.92;
    return { cx, cy, w: glassW, h: glassH, taper: 0.82 };
  }

  getStrawInlet() {
    const b = this.getGlassBounds();
    return [b.cx - b.w * 0.18, b.cy - b.h * 0.15];
  }

  getStrawRestTip() {
    const b = this.getGlassBounds();
    return [b.cx + b.w * 0.52, b.cy - b.h * 1.22];
  }

  update(dt, time, isSipping) {
    this.liquidLevel = V.lerp(this.liquidLevel, this.targetLevel, dt * 2.5);

    const b = this.getGlassBounds();
    const liquidTopY = b.cy - b.h * this.liquidLevel;
    const liquidBottomY = b.cy - b.h * 0.08;
    const liquidH = liquidBottomY - liquidTopY;

    for (const fb of this.fizz) {
      fb.y -= fb.speed * (isSipping ? 2.5 : 1) * dt;
      if (fb.y < 0) {
        fb.y = liquidH + Math.random() * 15;
        fb.x = (Math.random() - 0.5) * b.w * 0.7;
      }
    }
  }

  drawBack(ctx, time) {
    const b = this.getGlassBounds();
    const cx = b.cx;
    const cy = b.cy;
    const topW = b.w;
    const botW = b.w * b.taper;
    const h = b.h;

    ctx.save();

    // 1. Ambient table shadow with warm amber refraction glow
    const shadowGrad = ctx.createRadialGradient(cx, cy + 6, botW * 0.1, cx, cy + 6, botW * 0.9);
    shadowGrad.addColorStop(0, "rgba(255, 122, 0, 0.35)");
    shadowGrad.addColorStop(0.45, "rgba(0, 0, 0, 0.45)");
    shadowGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = shadowGrad;
    ctx.beginPath();
    ctx.ellipse(cx, cy + 6, botW * 0.85, 18, 0, 0, Math.PI * 2);
    ctx.fill();

    // 2. Glass silhouette backdrop
    ctx.beginPath();
    ctx.moveTo(cx - topW * 0.5, cy - h);
    ctx.lineTo(cx - botW * 0.5, cy);
    ctx.lineTo(cx + botW * 0.5, cy);
    ctx.lineTo(cx + topW * 0.5, cy - h);
    ctx.closePath();
    ctx.fillStyle = "rgba(255, 255, 255, 0.05)";
    ctx.fill();

    // 3. Orange Juice Volume
    if (this.liquidLevel > 0.02) {
      const curTopY = cy - h * this.liquidLevel;
      const curWidth = V.lerp(botW, topW, this.liquidLevel);

      ctx.save();
      ctx.beginPath();
      ctx.moveTo(cx - curWidth * 0.5 + 4, curTopY);
      ctx.lineTo(cx - botW * 0.5 + 6, cy - 8);
      ctx.quadraticCurveTo(cx, cy - 3, cx + botW * 0.5 - 6, cy - 8);
      ctx.lineTo(cx + curWidth * 0.5 - 4, curTopY);
      ctx.closePath();
      ctx.clip();

      const juiceGrad = ctx.createLinearGradient(cx - curWidth * 0.5, curTopY, cx + curWidth * 0.5, cy);
      juiceGrad.addColorStop(0, "#FF6B00");
      juiceGrad.addColorStop(0.3, "#FF8800");
      juiceGrad.addColorStop(0.7, "#FFA726");
      juiceGrad.addColorStop(1, "#FF5722");
      ctx.fillStyle = juiceGrad;
      ctx.fill();

      const innerShadow = ctx.createRadialGradient(cx, curTopY + 40, curWidth * 0.1, cx, curTopY + 40, curWidth * 0.65);
      innerShadow.addColorStop(0, "rgba(255, 213, 79, 0.35)");
      innerShadow.addColorStop(0.7, "rgba(230, 81, 0, 0.1)");
      innerShadow.addColorStop(1, "rgba(191, 54, 12, 0.45)");
      ctx.fillStyle = innerShadow;
      ctx.fill();

      // Natural pulp specks
      for (const p of this.pulp) {
        const px = cx + p.x * (curWidth / topW) * 0.85;
        const py = curTopY + 12 + (p.y % Math.max(10, cy - curTopY - 18));
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = 0.55;
        ctx.beginPath();
        ctx.ellipse(0, 0, p.rx, p.ry, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      // Effervescent rising fizz bubbles
      ctx.fillStyle = "rgba(255, 255, 255, 0.75)";
      for (const fb of this.fizz) {
        const bx = cx + fb.x * (curWidth / topW) * 0.8;
        const by = curTopY + fb.y;
        if (by >= curTopY && by <= cy - 10) {
          ctx.beginPath();
          ctx.arc(bx, by, fb.r, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      ctx.restore(); // end juice clip

      // 4. Liquid Surface Meniscus
      const menuH = Math.min(11, 11 * (this.liquidLevel / 0.15));
      ctx.beginPath();
      ctx.ellipse(cx, curTopY, Math.max(2, curWidth * 0.5 - 4), menuH, 0, 0, Math.PI * 2);
      const surfaceGrad = ctx.createRadialGradient(cx, curTopY, curWidth * 0.05, cx, curTopY, curWidth * 0.5);
      surfaceGrad.addColorStop(0, "rgba(255, 238, 88, 0.95)");
      surfaceGrad.addColorStop(0.65, "rgba(255, 167, 38, 0.9)");
      surfaceGrad.addColorStop(1, "rgba(239, 108, 0, 0.85)");
      ctx.fillStyle = surfaceGrad;
      ctx.fill();
      ctx.strokeStyle = "rgba(255, 255, 255, 0.45)";
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }

    // 5. Floating / Resting Ice Cubes
    const floatTopY = cy - h * Math.max(0.08, this.liquidLevel);
    for (const ic of this.ice) {
      const bobY = Math.sin(time * 2.2 + ic.bob) * (this.liquidLevel > 0.15 ? 3 : 0.6);
      const ix = cx + ic.x;
      const iy = Math.min(cy - 22, floatTopY + ic.y + bobY + 16);
      this.drawIceCube(ctx, ix, iy, ic.size, ic.rot);
    }

    ctx.restore();
  }

  drawIceCube(ctx, x, y, size, rot) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);

    const s = size * 0.5;
    ctx.beginPath();
    ctx.roundRect(-s, -s, size, size, 8);

    const iceGrad = ctx.createLinearGradient(-s, -s, s, s);
    iceGrad.addColorStop(0, "rgba(240, 248, 255, 0.75)");
    iceGrad.addColorStop(0.4, "rgba(224, 242, 254, 0.35)");
    iceGrad.addColorStop(0.8, "rgba(255, 204, 128, 0.45)");
    iceGrad.addColorStop(1, "rgba(255, 167, 38, 0.3)");
    ctx.fillStyle = iceGrad;
    ctx.fill();

    ctx.strokeStyle = "rgba(255, 255, 255, 0.85)";
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = "rgba(255, 255, 255, 0.9)";
    ctx.beginPath();
    ctx.ellipse(-s + 7, -s + 7, 5, 2.5, -0.6, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  drawFront(ctx, time) {
    const b = this.getGlassBounds();
    const cx = b.cx;
    const cy = b.cy;
    const topW = b.w;
    const botW = b.w * b.taper;
    const h = b.h;

    ctx.save();

    // 1. Fresh Orange Slice Garnish (hooked onto rim)
    this.drawOrangeSlice(ctx, cx - topW * 0.38, cy - h - 14, 58, 0.35);

    // 2. Thick Crystal Base (heavy solid glass bottom)
    ctx.beginPath();
    ctx.moveTo(cx - botW * 0.5, cy - 18);
    ctx.lineTo(cx - botW * 0.5, cy);
    ctx.quadraticCurveTo(cx, cy + 4, cx + botW * 0.5, cy);
    ctx.lineTo(cx + botW * 0.5, cy - 18);
    ctx.quadraticCurveTo(cx, cy - 14, cx - botW * 0.5, cy - 18);
    ctx.closePath();
    const baseGrad = ctx.createLinearGradient(cx - botW * 0.5, cy - 18, cx + botW * 0.5, cy);
    baseGrad.addColorStop(0, "rgba(255, 255, 255, 0.35)");
    baseGrad.addColorStop(0.2, "rgba(255, 255, 255, 0.15)");
    baseGrad.addColorStop(0.5, "rgba(255, 255, 255, 0.45)");
    baseGrad.addColorStop(0.8, "rgba(255, 255, 255, 0.15)");
    baseGrad.addColorStop(1, "rgba(255, 255, 255, 0.35)");
    ctx.fillStyle = baseGrad;
    ctx.fill();
    ctx.strokeStyle = "rgba(255, 255, 255, 0.6)";
    ctx.lineWidth = 2;
    ctx.stroke();

    // 3. Specular Reflections along the glass sides
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx - topW * 0.46, cy - h);
    ctx.lineTo(cx - botW * 0.46, cy - 18);
    ctx.lineTo(cx - botW * 0.38, cy - 18);
    ctx.lineTo(cx - topW * 0.38, cy - h);
    ctx.closePath();
    const leftSheen = ctx.createLinearGradient(cx - topW * 0.46, 0, cx - topW * 0.38, 0);
    leftSheen.addColorStop(0, "rgba(255, 255, 255, 0.65)");
    leftSheen.addColorStop(0.5, "rgba(255, 255, 255, 0.25)");
    leftSheen.addColorStop(1, "rgba(255, 255, 255, 0)");
    ctx.fillStyle = leftSheen;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(cx + topW * 0.44, cy - h);
    ctx.lineTo(cx + botW * 0.44, cy - 18);
    ctx.lineTo(cx + botW * 0.48, cy - 18);
    ctx.lineTo(cx + topW * 0.48, cy - h);
    ctx.closePath();
    const rightSheen = ctx.createLinearGradient(cx + topW * 0.44, 0, cx + topW * 0.48, 0);
    rightSheen.addColorStop(0, "rgba(255, 255, 255, 0)");
    rightSheen.addColorStop(1, "rgba(255, 255, 255, 0.55)");
    ctx.fillStyle = rightSheen;
    ctx.fill();
    ctx.restore();

    // 4. Cold Glistening Condensation Beads
    for (const bead of this.condensation) {
      const bx = cx + bead.u * topW;
      const by = cy - h + bead.v * h + Math.sin(time * 0.5 + bead.u * 10) * bead.drip;
      if (by < cy - 14) {
        ctx.fillStyle = "rgba(0, 0, 0, 0.18)";
        ctx.beginPath();
        ctx.arc(bx + 0.8, by + 1, bead.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = "rgba(255, 255, 255, 0.7)";
        ctx.beginPath();
        ctx.arc(bx, by, bead.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath();
        ctx.arc(bx - bead.r * 0.35, by - bead.r * 0.35, bead.r * 0.35, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // 5. Glass Rim Outline & Highball Contour
    ctx.beginPath();
    ctx.moveTo(cx - topW * 0.5, cy - h);
    ctx.lineTo(cx - botW * 0.5, cy);
    ctx.quadraticCurveTo(cx, cy + 4, cx + botW * 0.5, cy);
    ctx.lineTo(cx + topW * 0.5, cy - h);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.75)";
    ctx.lineWidth = 2.5;
    ctx.stroke();

    ctx.beginPath();
    ctx.ellipse(cx, cy - h, topW * 0.5, 12, 0, 0, Math.PI * 2);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.9)";
    ctx.lineWidth = 2.5;
    ctx.stroke();

    ctx.restore();
  }

  drawOrangeSlice(ctx, x, y, radius, angle) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, Math.PI * 2);
    ctx.fillStyle = "#FF6D00";
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, radius - 4, 0, Math.PI * 2);
    ctx.fillStyle = "#FFF9E6";
    ctx.fill();

    const numSegments = 8;
    const segRadius = radius - 8;
    ctx.fillStyle = "#FFA000";

    for (let i = 0; i < numSegments; i++) {
      const a1 = (i / numSegments) * Math.PI * 2 + 0.08;
      const a2 = ((i + 1) / numSegments) * Math.PI * 2 - 0.08;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, segRadius, a1, a2);
      ctx.closePath();
      ctx.fill();
    }

    ctx.fillStyle = "#FFF9E6";
    ctx.beginPath();
    ctx.arc(0, 0, 7, 0, Math.PI * 2);
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, radius - 2, -Math.PI * 0.35, Math.PI * 0.25);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.75)";
    ctx.lineWidth = 2.5;
    ctx.stroke();

    ctx.clearRect(-5, radius * 0.4, 10, radius * 0.65);

    ctx.restore();
  }
}

// Interactive Straw Controller
class StrawController {
  constructor(drink) {
    this.drink = drink;
    this.tip = [0, 0];
    this.restTip = [0, 0];
    this.inlet = [0, 0];
    this.isHeld = false;
    this.atMouth = false;
    this.isSipping = false;
    this.siphonProgress = 0;
    this.thirstSipped = 0;
    this.reachTimer = 0;
    this.releaseTimer = 0;
    this.touchActive = false;
  }

  reset() {
    this.inlet = this.drink.getStrawInlet();
    this.restTip = this.drink.getStrawRestTip();
    this.tip = [this.restTip[0], this.restTip[1]];
    this.isHeld = false;
    this.atMouth = false;
    this.isSipping = false;
    this.siphonProgress = 0;
    this.thirstSipped = 0;
  }

  update(hand, face, dt, time) {
    this.inlet = this.drink.getStrawInlet();
    this.restTip = this.drink.getStrawRestTip();

    let targetTip = [this.restTip[0], this.restTip[1]];

    if (this.touchActive) {
      // Touch/Mouse active
    } else if (hand) {
      const dToTip = V.dist(hand.gripPoint, this.tip);
      if (!this.isHeld) {
        if (dToTip < CFG.PICKUP_RADIUS && hand.grip >= CFG.GRIP_ON) {
          this.isHeld = true;
          this.releaseTimer = 0;
          sfx.playClink();
        }
      } else {
        if (hand.grip < CFG.GRIP_OFF) {
          this.releaseTimer += dt;
          if (this.releaseTimer > 0.4) {
            this.isHeld = false;
          }
        } else {
          this.releaseTimer = 0;
        }
      }

      if (this.isHeld) {
        targetTip = [hand.gripPoint[0], hand.gripPoint[1]];
      }
    } else {
      this.isHeld = false;
    }

    if (face) {
      const dMouth = V.dist(this.isHeld ? targetTip : this.tip, face.mouthCenter);
      const mouthSnapDist = Math.max(CFG.AT_MOUTH_RADIUS, face.faceWidth * 0.45);

      if (dMouth < mouthSnapDist && (this.isHeld || this.touchActive)) {
        this.atMouth = true;
        targetTip = [face.mouthCenter[0], face.mouthCenter[1]];
      } else {
        this.atMouth = false;
      }
    } else {
      this.atMouth = false;
    }

    const rate = this.atMouth ? CFG.SNAP_RATE : (this.isHeld ? CFG.HAND_RATE : CFG.RETURN_RATE);
    this.tip = V.lerpV(this.tip, targetTip, 1 - Math.exp(-rate * dt));

    const wasSipping = this.isSipping;
    if (this.atMouth && face) {
      const puckerVal = Math.max(face.pucker || 0, face.funnel || 0);
      this.isSipping = puckerVal > CFG.PUCKER_THRESHOLD;
    } else {
      this.isSipping = false;
    }

    if (this.isSipping) {
      if (!wasSipping) sfx.startSip();
      this.siphonProgress = Math.min(1, this.siphonProgress + dt * 3.5);

      if (this.siphonProgress >= 0.7 && this.drink.liquidLevel > 0.01) {
        this.thirstSipped = Math.min(1, this.thirstSipped + dt * 0.32);
        this.drink.drainSip(dt * 0.28); // Drains ~28% per second -> 3 to 4 sips empty the whole glass!
      } else if (this.drink.liquidLevel <= 0.01) {
        this.thirstSipped = 1.0;
        this.siphonProgress = Math.max(0, this.siphonProgress - dt * 2.0);
      }
    } else {
      if (wasSipping) sfx.stopSip();
      this.siphonProgress = Math.max(0, this.siphonProgress - dt * 2.2);
    }

    return {
      isHeld: this.isHeld,
      atMouth: this.atMouth,
      isSipping: this.isSipping,
      progress: this.thirstSipped,
      tip: this.tip,
      inlet: this.inlet
    };
  }

  draw(ctx, time) {
    const p1 = this.inlet;
    const p2 = this.tip;
    const strawLen = V.dist(p1, p2);
    const dir = V.norm(V.sub(p2, p1));
    const norm = [-dir[1], dir[0]];
    const radius = 7.5;

    ctx.save();

    const bendPoint = V.lerpV(p1, p2, 0.72);
    const midCtrl = V.add(bendPoint, V.mul(norm, 6 * Math.sin(time * 2)));

    ctx.lineWidth = radius * 2;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    ctx.strokeStyle = "rgba(255, 255, 255, 0.88)";
    ctx.beginPath();
    ctx.moveTo(p1[0], p1[1]);
    ctx.quadraticCurveTo(midCtrl[0], midCtrl[1], p2[0], p2[1]);
    ctx.stroke();

    // Stripes along the straw
    const numStripes = Math.floor(strawLen / 18);
    for (let i = 0; i < numStripes; i++) {
      const t = i / numStripes;
      const sp = V.lerpV(p1, p2, t);
      const angle = Math.atan2(dir[1], dir[0]) + 0.65;
      const stripeLen = 14;
      ctx.strokeStyle = (i % 2 === 0) ? "#FF5722" : "#FFA000";
      ctx.lineWidth = 4.5;
      ctx.beginPath();
      ctx.moveTo(sp[0] - Math.cos(angle) * stripeLen, sp[1] - Math.sin(angle) * stripeLen);
      ctx.lineTo(sp[0] + Math.cos(angle) * stripeLen, sp[1] + Math.sin(angle) * stripeLen);
      ctx.stroke();
    }

    // Dynamic Rising Orange Juice Column
    if (this.siphonProgress > 0.05) {
      const juiceEnd = V.lerpV(p1, p2, this.siphonProgress);
      ctx.lineWidth = radius * 1.45;
      ctx.lineCap = "round";
      ctx.strokeStyle = "#FF6D00";

      ctx.beginPath();
      ctx.moveTo(p1[0], p1[1]);
      ctx.quadraticCurveTo(midCtrl[0], midCtrl[1], juiceEnd[0], juiceEnd[1]);
      ctx.stroke();

      ctx.lineWidth = radius * 0.6;
      ctx.strokeStyle = "#FFD54F";
      ctx.beginPath();
      ctx.moveTo(p1[0], p1[1]);
      ctx.quadraticCurveTo(midCtrl[0], midCtrl[1], juiceEnd[0], juiceEnd[1]);
      ctx.stroke();

      const bubbleT = (time * 4) % 1;
      const bubblePos = V.lerpV(p1, juiceEnd, bubbleT);
      ctx.fillStyle = "#FFFFFF";
      ctx.beginPath();
      ctx.arc(bubblePos[0], bubblePos[1], 2.2, 0, Math.PI * 2);
      ctx.fill();
    }

    // Straw Mouthpiece Tip Ring
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.ellipse(p2[0], p2[1], radius, radius * 0.6, Math.atan2(dir[1], dir[0]), 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#FF5722";
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Interactive Grab Cue
    if (!this.isHeld && !this.atMouth) {
      const pulse = 0.5 + 0.5 * Math.sin(time * 3);
      ctx.beginPath();
      ctx.arc(p2[0], p2[1], 22 + pulse * 6, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(255, 122, 0, ${0.45 + pulse * 0.4})`;
      ctx.lineWidth = 2.5;
      ctx.stroke();
    }

    ctx.restore();
  }
}

// MediaPipe Vision Detector Wrapper
class VisionDetector {
  constructor() {
    this.hands = null;
    this.face = null;
    this.fileset = null;
    this.result = { hands: [], face: null };
  }

  async init(onProgress) {
    onProgress?.("Loading vision engines…", 0.15);
    this.fileset = await FilesetResolver.forVisionTasks(WASM_PATH);

    onProgress?.("Loading hand tracker…", 0.4);
    const handBlob = await fetch(HAND_MODEL_PATH).then(r => r.arrayBuffer());
    this.hands = await HandLandmarker.createFromOptions(this.fileset, {
      baseOptions: { modelAssetBuffer: new Uint8Array(handBlob), delegate: "GPU" },
      runningMode: "VIDEO",
      numHands: 2,
      minHandDetectionConfidence: 0.5,
      minHandPresenceConfidence: 0.4,
      minTrackingConfidence: 0.4
    }).catch(async () => {
      return await HandLandmarker.createFromOptions(this.fileset, {
        baseOptions: { modelAssetBuffer: new Uint8Array(handBlob), delegate: "CPU" },
        runningMode: "VIDEO",
        numHands: 2
      });
    });

    onProgress?.("Loading face tracker…", 0.75);
    const faceBlob = await fetch(FACE_MODEL_PATH).then(r => r.arrayBuffer());
    this.face = await FaceLandmarker.createFromOptions(this.fileset, {
      baseOptions: { modelAssetBuffer: new Uint8Array(faceBlob), delegate: "GPU" },
      runningMode: "VIDEO",
      numFaces: 1,
      outputFaceBlendshapes: true,
      minFaceDetectionConfidence: 0.5,
      minFacePresenceConfidence: 0.4,
      minTrackingConfidence: 0.4
    }).catch(async () => {
      return await FaceLandmarker.createFromOptions(this.fileset, {
        baseOptions: { modelAssetBuffer: new Uint8Array(faceBlob), delegate: "CPU" },
        runningMode: "VIDEO",
        numFaces: 1,
        outputFaceBlendshapes: true
      });
    });

    onProgress?.("Ready!", 1.0);
  }

  detect(video, videoToCanvas, timestamp) {
    const res = { hands: [], face: null };
    try {
      if (this.hands) {
        const hRes = this.hands.detectForVideo(video, timestamp);
        if (hRes && hRes.landmarks) {
          res.hands = hRes.landmarks.map(lm => {
            const mapped = lm.map(p => videoToCanvas(p.x, p.y));
            const pts = [0, 5, 9, 13, 17].map(idx => mapped[idx]);
            const gripPoint = [
              pts.reduce((acc, p) => acc + p[0], 0) / pts.length,
              pts.reduce((acc, p) => acc + p[1], 0) / pts.length
            ];
            let gripScore = 0;
            const fingerTips = [[5, 8], [9, 12], [13, 16], [17, 20]];
            for (const [knuckle, tip] of fingerTips) {
              const dBase = V.dist(mapped[knuckle], mapped[0]) + 1e-5;
              const dTip = V.dist(mapped[tip], mapped[0]);
              gripScore += V.clamp((1.8 - dTip / dBase) / 0.8, 0, 1);
            }
            return {
              gripPoint,
              grip: gripScore / fingerTips.length,
              landmarks: mapped
            };
          });
        }
      }

      if (this.face) {
        const fRes = this.face.detectForVideo(video, timestamp);
        if (fRes && fRes.faceLandmarks && fRes.faceLandmarks.length > 0) {
          const lm = fRes.faceLandmarks[0].map(p => videoToCanvas(p.x, p.y));
          const lipIndices = [13, 14, 0, 17, 61, 291, 78, 308, 82, 312, 87, 317];
          let lx = 0, ly = 0;
          for (const idx of lipIndices) {
            lx += lm[idx][0];
            ly += lm[idx][1];
          }
          const mouthCenter = [lx / lipIndices.length, ly / lipIndices.length];
          const mouthWidth = V.dist(lm[61], lm[291]);
          const faceWidth = V.dist(lm[234], lm[454]);

          let pucker = 0, funnel = 0, jawOpen = 0, cheekPuff = 0;
          if (fRes.faceBlendshapes && fRes.faceBlendshapes[0]) {
            for (const cat of fRes.faceBlendshapes[0].categories) {
              if (cat.categoryName === "mouthPucker") pucker = cat.score;
              else if (cat.categoryName === "mouthFunnel") funnel = cat.score;
              else if (cat.categoryName === "jawOpen") jawOpen = cat.score;
              else if (cat.categoryName === "cheekPuff") cheekPuff = cat.score;
            }
          }

          res.face = {
            mouthCenter,
            mouthWidth,
            faceWidth,
            pucker,
            funnel,
            jawOpen,
            cheekPuff
          };
        }
      }
    } catch (e) {}
    return res;
  }
}

// Main Application Controller
class FreshSqueezeApp {
  constructor() {
    this.canvas = document.getElementById("stage");
    this.ctx = this.canvas.getContext("2d", { alpha: false, desynchronized: true });
    this.video = document.getElementById("cam");

    this.drink = new GlassDrinkRenderer(this.canvas.width, this.canvas.height);
    this.straw = new StrawController(this.drink);
    this.particles = new ParticleSystem();
    this.detector = new VisionDetector();

    this.ui = {
      intro: document.getElementById("intro"),
      startBtn: document.getElementById("start"),
      introNote: document.getElementById("intro-note"),
      coach: document.getElementById("coach"),
      step: document.getElementById("coach-step"),
      hint: document.getElementById("coach-hint"),
      meter: document.getElementById("coach-meter"),
      fill: document.getElementById("coach-fill"),
      debug: document.getElementById("coach-debug"),
      resetBtn: document.getElementById("reset"),
      toast: document.getElementById("vibed")
    };

    this.w = 0;
    this.h = 0;
    this.scale = 1;
    this.videoTransform = { ox: 0, oy: 0, s: 1, vw: CFG.CAMERA_WIDTH, vh: CFG.CAMERA_HEIGHT };
    this.lastTime = performance.now();
    this.fps = 60;
    this.showDebug = false;
    this.isRunning = false;
    this.lastSipCelebrated = false;

    this.setupListeners();
    this.resize();
    this.straw.reset();
  }

  setupListeners() {
    window.addEventListener("resize", () => this.resize());
    this.ui.startBtn?.addEventListener("click", () => this.startCamera());
    this.ui.resetBtn?.addEventListener("click", () => this.refillDrink());

    window.addEventListener("keydown", (e) => {
      if (e.key === "r" || e.key === "R") this.refillDrink();
      if (e.key === "d" || e.key === "D") this.showDebug = !this.showDebug;
    });

    let isDragging = false;
    const getPos = (e) => {
      const rect = this.canvas.getBoundingClientRect();
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      return [(clientX - rect.left) * (this.w / rect.width), (clientY - rect.top) * (this.h / rect.height)];
    };

    const onDown = (e) => {
      const [px, py] = getPos(e);
      if (V.dist([px, py], this.straw.tip) < CFG.PICKUP_RADIUS * 1.5) {
        isDragging = true;
        this.straw.touchActive = true;
        this.straw.tip = [px, py];
        sfx.playClink();
      }
    };
    const onMove = (e) => {
      if (!isDragging) return;
      const [px, py] = getPos(e);
      this.straw.tip = [px, py];
    };
    const onUp = () => {
      if (isDragging) {
        isDragging = false;
        this.straw.touchActive = false;
      }
    };

    this.canvas.addEventListener("mousedown", onDown);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);

    this.canvas.addEventListener("touchstart", onDown, { passive: false });
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onUp);
  }

  refillDrink() {
    this.drink.refill();
    this.straw.reset();
    this.particles.reset();
    this.lastSipCelebrated = false;
    sfx.playSplash();
    this.showToast("🍊 Freshly refilled!");
  }

  showToast(msg) {
    if (!this.ui.toast) return;
    this.ui.toast.textContent = msg;
    this.ui.toast.hidden = false;
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => {
      this.ui.toast.hidden = true;
    }, 2800);
  }

  resize() {
    const iw = Math.max(1, window.innerWidth);
    const ih = Math.max(1, window.innerHeight);
    const dpr = Math.min(window.devicePixelRatio || 1, Math.sqrt(CFG.MAX_CANVAS_PIXELS / (iw * ih)));
    this.w = Math.round(iw * dpr);
    this.h = Math.round(ih * dpr);
    this.canvas.width = this.w;
    this.canvas.height = this.h;
    this.drink.resize(this.w, this.h);
    this.updateVideoTransform();
  }

  updateVideoTransform() {
    const vw = this.video.videoWidth || CFG.CAMERA_WIDTH;
    const vh = this.video.videoHeight || CFG.CAMERA_HEIGHT;
    const s = Math.max(this.w / vw, this.h / vh);
    this.videoTransform = {
      s,
      ox: (this.w - vw * s) / 2,
      oy: (this.h - vh * s) / 2,
      vw,
      vh
    };
  }

  videoToCanvas(vx, vy) {
    const vt = this.videoTransform;
    return [vt.ox + (1 - vx) * vt.vw * vt.s, vt.oy + vy * vt.vh * vt.s];
  }

  async startCamera() {
    this.ui.startBtn.disabled = true;
    this.ui.startBtn.textContent = "Opening camera…";

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: CFG.CAMERA_WIDTH }, height: { ideal: CFG.CAMERA_HEIGHT }, facingMode: "user" },
        audio: false
      });
      this.video.srcObject = stream;
      await this.video.play();
      this.updateVideoTransform();

      this.ui.intro.classList.add("leaving");
      setTimeout(() => { this.ui.intro.hidden = true; }, 380);

      await this.detector.init((status, prog) => {
        this.ui.hint.textContent = status;
        this.ui.fill.style.width = `${Math.round(prog * 100)}%`;
      });

      this.isRunning = true;
    } catch (err) {
      console.error(err);
      this.ui.startBtn.disabled = false;
      this.ui.startBtn.textContent = "Try again";
      this.ui.introNote.textContent = "Camera access was denied or not found. You can still drag the straw with your mouse or finger!";
      this.ui.introNote.classList.add("error");
      setTimeout(() => {
        this.ui.intro.classList.add("leaving");
        setTimeout(() => { this.ui.intro.hidden = true; }, 380);
        this.isRunning = true;
      }, 2000);
    }
  }

  updateHUD(state) {
    let step = "Step 1 of 3";
    let hint = "Reach out and grab the straw with your hand";

    if (state.isSipping) {
      step = "Step 3 of 3";
      hint = "Sipping cold orange juice! Keep going!";
    } else if (state.atMouth) {
      step = "Step 3 of 3";
      hint = "Pucker your lips around the straw to sip!";
    } else if (state.isHeld) {
      step = "Step 2 of 3";
      hint = "Bring the straw up to your lips";
    }

    if (state.progress >= 0.98 || this.drink.liquidLevel <= 0.02) {
      step = "All Finished!";
      hint = "Glass is empty! 🍊 Super refreshing! Press 'R' to refill!";
      if (!this.lastSipCelebrated) {
        this.lastSipCelebrated = true;
        sfx.playSplash();
        this.particles.emitSplash(state.tip, 45);
        this.showToast("🍊 All finished! Press (R) to refill ✨");
      }
    }

    this.ui.step.textContent = step;
    this.ui.hint.textContent = hint;
    const pct = Math.round(state.progress * 100);
    this.ui.fill.style.width = `${pct}%`;
    this.ui.meter.setAttribute("aria-valuenow", String(pct));
  }

  loop(now) {
    requestAnimationFrame((t) => this.loop(t));
    const dt = Math.min(0.08, (now - this.lastTime) / 1000);
    this.lastTime = now;
    this.fps = this.fps * 0.9 + (1 / Math.max(dt, 0.001)) * 0.1;
    const time = now / 1000;

    let vision = { hands: [], face: null };
    const hasVideo = this.video.readyState >= 2 && this.video.videoWidth > 0;

    if (hasVideo) {
      this.updateVideoTransform();
      if (this.isRunning) {
        vision = this.detector.detect(this.video, (x, y) => this.videoToCanvas(x, y), now);
      }
    }

    if (hasVideo) {
      const vt = this.videoTransform;
      this.ctx.save();
      this.ctx.translate(this.w, 0);
      this.ctx.scale(-1, 1);
      this.ctx.drawImage(this.video, vt.ox, vt.oy, vt.vw * vt.s, vt.vh * vt.s);
      this.ctx.restore();
      this.ctx.fillStyle = "rgba(30, 20, 10, 0.18)";
      this.ctx.fillRect(0, 0, this.w, this.h);
    } else {
      const bg = this.ctx.createLinearGradient(0, 0, 0, this.h);
      bg.addColorStop(0, "#251C17");
      bg.addColorStop(0.7, "#1B1410");
      bg.addColorStop(1, "#120D0A");
      this.ctx.fillStyle = bg;
      this.ctx.fillRect(0, 0, this.w, this.h);
    }

    const activeHand = vision.hands.length > 0 ? vision.hands[0] : null;
    const strawState = this.straw.update(activeHand, vision.face, dt, time);
    this.drink.update(dt, time, strawState.isSipping);

    if (strawState.isSipping) {
      this.particles.emitSipDroplets(strawState.tip, 1.2);
    }
    this.particles.update(dt);

    // Draw Layers
    this.drink.drawBack(this.ctx, time);
    this.straw.draw(this.ctx, time);
    this.drink.drawFront(this.ctx, time);
    this.particles.draw(this.ctx);

    this.updateHUD(strawState);

    if (this.showDebug) {
      this.ctx.fillStyle = "#FF7A00";
      this.ctx.font = "13px monospace";
      this.ctx.fillText(`${Math.round(this.fps)} FPS | Hands: ${vision.hands.length} | Face: ${vision.face ? "yes" : "no"} | Sip: ${strawState.isSipping ? "YES" : "no"}`, 20, this.h - 30);
    }
  }

  start() {
    this.loop(performance.now());
  }
}

const app = new FreshSqueezeApp();
app.start();
